import assert from "node:assert/strict";
import {readFileSync} from "node:fs";
import {createHash} from "node:crypto";
import {execFileSync} from "node:child_process";
const root="/home/apnex/taceng/agp";
const sha256=value=>createHash("sha256").update(value).digest("hex");
const read=name=>readFileSync(root+"/"+name);
const expected={
  "heads": {
    "agp": "0aa6be75ccacf4e2c3770a49c5ea39970a25a98a",
    "zorg": "53923cbee49dc16f1ab16fb0af6a2182a4ae26bb"
  },
  "before": [
    {
      "path": "docs/BOARD.md",
      "sha256": "af0a80eeb381bc1f04da42b702017226d218209e47445c7a089091d370986876",
      "bytes": 45725
    },
    {
      "path": "docs/VERIFICATION.md",
      "sha256": "210efa7c0c8bdaa86bd8bc02f0e7131fa225f8837877ccc2a42ca1bbcda79e2b",
      "bytes": 287830
    },
    {
      "path": "docs/design/mechanisms.md",
      "sha256": "3d00bc685488f81e54d31e12cd00f579f86421db00ee37fb9de26c4d1b74a99d",
      "bytes": 30420
    }
  ],
  "boardLines": [
    {
      "line": 228,
      "before": "| 4 | `B51` | Advisory review recommends direct-only egress; the identity association remains to be agreed | [Reply-isolation review](reviews/reply-isolation-review.md) separates endpoint pins from authorized channels, identifies the conflicting relay clause and the principal-continuity boundary, and preserves D26 for ordinary sends; no public contract or implementation is approved |"
    },
    {
      "line": 294,
      "before": "Status: the scale amendment is drafted, not ratified; the reply-isolation review recommends direct-only egress with an explicit principal-continuity obligation, while the joint lifecycle proposal remains under review.\\"
    },
    {
      "line": 302,
      "before": "| `B51` | Agree direct-only reply scope and the principal-association boundary | [Advisory review](reviews/reply-isolation-review.md) requires reconciliation of Zorg's relay clause and either a proved stable node-to-principal admission invariant or an explicit immutable association; shared send enforcement and consumer adoption remain unbuilt, and server push is deferred |"
    },
    {
      "line": 344,
      "before": "| Do we agree direct-only reply egress and its principal-association contract before choosing public types? | `B51` design selection; [review](reviews/reply-isolation-review.md) recommends excluding AGP relays from this guarantee and agreeing the admission invariant or immutable association with Zorg; ordinary D26 behavior remains unchanged |"
    }
  ]
};
const currentLines=read("docs/BOARD.md").toString().split("\n");
const boardChanges=expected.boardLines.map(item=>({...item,after:currentLines[item.line-1]}));
for (const change of boardChanges) {
  assert.notEqual(change.before,change.after,"board readiness entry unchanged");
  currentLines[change.line-1]=change.before;
}
assert.equal(sha256(currentLines.join("\n")),expected.before.find(x=>x.path==="docs/BOARD.md").sha256,"unrelated board content changed");
const verification=read("docs/VERIFICATION.md").toString();
const start=verification.indexOf("### 4.48 Reply isolation response placement\n");
const end=verification.indexOf("## 5. Modular test architecture",start);
assert.ok(start>=0 && end>start);
assert.equal(sha256(verification.slice(0,start)+verification.slice(end)),expected.before.find(x=>x.path==="docs/VERIFICATION.md").sha256,"earlier verification content changed");
assert.equal(sha256(read("docs/design/mechanisms.md")),expected.before.find(x=>x.path==="docs/design/mechanisms.md").sha256,"existing mechanisms edit changed");
const response=read("docs/reviews/reply-isolation-response.md");
const incoming=readFileSync("/home/apnex/taceng/zorg/upstream/incoming/agp-reply-isolation-response.md");
assert.ok(response.equals(incoming),"incoming draft differs from retained copy");
const sourceManifest=JSON.parse(read("docs/reviews/reply-isolation-sources.json"));
let sourcesChecked=0;
for (const repo of sourceManifest.repositories) {
  for (const file of repo.files) {
    assert.equal(sha256(readFileSync(repo.root+"/"+file.path)),file.sha256,"review source changed: "+file.path);
    sourcesChecked++;
  }
}
const agpHead=execFileSync("git",["rev-parse","HEAD"],{cwd:root,encoding:"utf8"}).trim();
assert.equal(agpHead,expected.heads.agp,"AGP HEAD changed");
const zorgHead=execFileSync("git",["rev-parse","HEAD"],{cwd:"/home/apnex/taceng/zorg",encoding:"utf8"}).trim();
const zorgStatus=execFileSync("git",["status","--short"],{cwd:"/home/apnex/taceng/zorg",encoding:"utf8"});
const artifacts=["docs/reviews/reply-isolation-response.md","docs/BOARD.md","docs/VERIFICATION.md"].map(path=>({path,sha256:sha256(read(path)),bytes:read(path).length}));
console.log(JSON.stringify({scope:"Author-only copy identity, source identity and pre-existing record preservation",identicalCopies:true,responseSha256:sha256(response),responseBytes:response.length,sourcesChecked,boardChanges,existingVerificationPreserved:true,existingMechanismsPreserved:true,agpHead,zorgHead,zorgStatus,artifacts},null,2));
